def holes(s: str) -> list[str]:
    return sorted(re.findall(r"\{(\w+)\}", s))


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--apply", action="store_true")
    ap.add_argument("--report", action="store_true")
    args = ap.parse_args()

    table = json.loads(DE.read_text(encoding="utf-8"))
    missing = [k for k in TRANSLATIONS if k not in table]
    dummy_missing = [k for k in DUMMY_FIXES if k not in table]
    assert not dummy_missing, f"dummy fixes absent: {dummy_missing[:3]}"
    dupes = [k for k in TRANSLATIONS if k in table]
    for en, said in list(TRANSLATIONS.items()) + list(DUMMY_FIXES.items()):
        assert holes(en) == holes(said), f"holes differ: {en!r}"
        assert said.strip(), f"empty value: {en!r}"
    print(f"de.json: {len(table)} keys; TRANSLATIONS holds {len(TRANSLATIONS)}; "
          f"absent from the catalog: {len(missing)}; already present: {len(dupes)}")
    if missing:
        for k in missing[:10]:
            print("  absent:", repr(k))
    if args.report or not args.apply:
        return 0
    table.update(TRANSLATIONS)
    table.update({k: v for k, v in DUMMY_FIXES.items() if k in table})
    DE.write_text(json.dumps(table, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(f"wrote {DE} with {len(table)} keys")
    return 0


if __name__ == "__main__":
    sys.exit(main())
